INSERT INTO aplicativos (nome, titulo_card, descricao_card, descricao_detalhada, recursos, publico_alvo, diferencial, icone, link_saiba_mais, ordem) VALUES
('BM Produção Lite', 'Ordens de Produção e Custos',
 'Ordens de produção simples e rápidas, com consumo de insumos, lotes, perdas e custo de cada produção.',
 'O BM Produção Lite leva o controle da produção para uma tela web moderna. Em cada ordem de produção você informa o que foi produzido, as matérias-primas consumidas e a equipe envolvida: o sistema dá baixa no estoque, registra a movimentação e calcula o custo, incluindo a mão de obra. Receitas usadas com frequência viram fichas técnicas, prontas para reaproveitar na próxima produção.',
 'Ordens de produção com produtos acabados, insumos consumidos e equipe\nFichas técnicas reutilizáveis para repetir produções em poucos cliques\nBaixa automática de estoque com custo médio e histórico de movimentação\nControle de lotes, perdas e conversão entre unidades\nCusto da produção com mão de obra por valor-hora e centro de custo\nImportação de itens de orçamentos e ordens de serviço do ERP\nPainel com indicadores e relatório de produção do período',
 'Pequenas e médias indústrias de alimentos, bebidas, químicos, cosméticos, confecção e montagem',
 'Trabalha direto na base do ERP BMsoft: estoque e custos atualizados na hora, sem sistema paralelo nem redigitação.',
 'industria', NULL, 9);
